// Appends Haircutting & Hair Styling questions ids 182-231
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'

const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/barber-questions.js')

const topic = `"Haircutting & Hair Styling"`
const topic_es = `"Corte de Cabello y Peinado"`
const psi_topic = `"Haircutting & Hair Styling"`
const psi_topic_es = `"Corte de Cabello y Peinado"`

const q = [
  { id: 182, question: "A 'line-up' (shape-up or edge-up) refers to:", question_es: "Un 'line-up' (perfilado o edge-up) se refiere a:", options: ["Defining and sharpening the hairline edges using a trimmer along the forehead, temples, and sideburns", "Creating a fade along the sides of the head", "Cutting a hard part into the hair", "Removing excess length from the crown area"], options_es: ["Definir y afinar los bordes de la línea del cabello usando una recortadora a lo largo de la frente, sienes y patillas", "Crear un degradé a lo largo de los lados de la cabeza", "Cortar una separación definida en el cabello", "Eliminar el exceso de longitud del área de la coronilla"], correct: 0, explanation: "A line-up (edge-up or shape-up) uses a trimmer to create sharp, defined lines along the natural hairline at the forehead, temples, and sideburns. It is a finishing technique that defines the overall shape of the haircut." },
  { id: 183, question: "A 'hard part' is created by:", question_es: "Una 'separación dura' se crea mediante:", options: ["Using a trimmer to cut a precise, defined line into the scalp to create a visible part line", "Using a wide-tooth comb to separate the hair along a natural parting", "Applying gel along the part line to hold it in place", "Cutting the hair shorter on one side to create a natural part"], options_es: ["Usar una recortadora para cortar una línea precisa y definida en el cuero cabelludo para crear una línea de separación visible", "Usar un peine de dientes anchos para separar el cabello a lo largo de una separación natural", "Aplicar gel a lo largo de la línea de separación para mantenerla en su lugar", "Cortar el cabello más corto en un lado para crear una separación natural"], correct: 0, explanation: "A hard part is an artificially cut line shaved into the scalp with a trimmer, creating a crisp, defined part. It mimics the look of a natural part but with sharper definition that holds regardless of how the hair moves." },
  { id: 184, question: "The 'disconnected undercut' is characterized by:", question_es: "El 'corte inferior desconectado' se caracteriza por:", options: ["An abrupt length difference between very long hair on top and very short (or shaved) sides, with no blending between the two lengths", "A gradual fade from short sides to longer top", "Even layering throughout the sides and top", "A textured top with a tapered nape only"], options_es: ["Una diferencia de longitud abrupta entre cabello muy largo arriba y lados muy cortos (o rapados), sin mezcla entre las dos longitudes", "Un degradé gradual de lados cortos a la parte superior más larga", "Capas uniformes en todo el lateral y la parte superior", "Parte superior texturizada con solo una nuca cónica"], correct: 0, explanation: "A disconnected undercut features a stark contrast between the long top and very short sides with NO blending or graduation. The dramatic difference between the two lengths is intentional and defines the style." },
  { id: 185, question: "A 'pompadour' style is characterized by:", question_es: "Un estilo 'pompadour' se caracteriza por:", options: ["Hair swept upward and back from the forehead, creating height and volume at the front", "Hair that is cut uniformly short all over the head", "Long layers pulled downward toward the face", "A shaved pattern cut into the sides with a longer top"], options_es: ["Cabello barrido hacia arriba y hacia atrás desde la frente, creando altura y volumen en la parte delantera", "Cabello cortado uniformemente corto en toda la cabeza", "Capas largas jaladas hacia abajo hacia el rostro", "Un patrón rapado cortado en los lados con una parte superior más larga"], correct: 0, explanation: "The pompadour features hair swept up and back from the forehead to create height at the front. Modern versions are often paired with a fade or undercut on the sides for a contemporary look." },
  { id: 186, question: "A 'crew cut' is characterized by:", question_es: "Un 'crew cut' se caracteriza por:", options: ["Hair that is cut short all over, slightly longer on top and tapered on the sides and back", "A shaved head with no hair remaining", "Long hair on top with closely shaved sides", "An even length all over using one clipper guard size"], options_es: ["Cabello cortado corto en todo el cabello, ligeramente más largo en la parte superior y cónico en los lados y la nuca", "Una cabeza rapada sin cabello", "Cabello largo arriba con lados muy rapados", "Una longitud uniforme en todo el cabello usando un solo tamaño de guarda"], correct: 0, explanation: "A crew cut is a classic men's cut with hair cut short all over — slightly longer on top (1/2 to 1 inch), with the top combed forward and the sides and back tapered. It creates a clean, conservative, low-maintenance style." },
  { id: 187, question: "A 'buzz cut' is created by:", question_es: "Un 'buzz cut' se crea mediante:", options: ["Running clippers with one guard size over the entire head for a uniformly short, even length all over", "Using scissors to cut hair evenly short throughout", "Creating a high fade with longer hair on top", "Cutting hair at 90-degree elevation all over"], options_es: ["Pasar las cortadoras con un tamaño de guarda sobre toda la cabeza para una longitud corta y uniforme en todo el cabello", "Usar tijeras para cortar el cabello uniformemente corto en todo el cabello", "Crear un degradé alto con cabello más largo en la parte superior", "Cortar el cabello a 90 grados de elevación en todo el cabello"], correct: 0, explanation: "A buzz cut uses one clipper guard (usually #1–#3) over the entire head without variation. The result is a uniform length all over. It is the fastest, most straightforward clipper cut with no blending required." },
  { id: 188, question: "The 'Caesar cut' is identified by:", question_es: "El 'corte César' se identifica por:", options: ["Short, horizontally cut bangs across the forehead with an evenly cut top, giving a Roman emperor appearance", "Long flowing locks worn down the back", "A shaved top with long sides", "A tight bun worn at the crown"], options_es: ["Flequillo corto cortado horizontalmente a través de la frente con una parte superior cortada uniformemente, dando apariencia de emperador romano", "Mechones largos y fluidos que caen por la espalda", "Parte superior rapada con lados largos", "Un moño apretado usado en la coronilla"], correct: 0, explanation: "The Caesar cut features short hair with horizontally cut, forward-combed bangs (fringe). The sides and back are short and tapered. It gives the appearance of a wreath — hence the Roman emperor reference." },
  { id: 189, question: "For a client with a square face shape, haircutting recommendations include:", question_es: "Para un cliente con forma de rostro cuadrado, las recomendaciones de corte de cabello incluyen:", options: ["Adding height and soft curves on top while keeping the sides less full to minimize wide jaw appearance", "Adding fullness at the jaw with wide sides", "Keeping even length all around to emphasize symmetry", "Maximizing volume at the temples and sides"], options_es: ["Añadir altura y curvas suaves en la parte superior mientras se mantienen los lados menos llenos para minimizar la apariencia de mandíbula ancha", "Añadir volumen en la mandíbula con lados anchos", "Mantener longitud uniforme en todo el cabello para enfatizar la simetría", "Maximizar el volumen en las sienes y los lados"], correct: 0, explanation: "A square face has a strong, wide jawline. Styles that add height on top and reduce bulk at the sides soften the strong angles of the jaw, creating a more oval appearance." },
  { id: 190, question: "For a client with an oblong (long) face shape, the barber should:", question_es: "Para un cliente con forma de rostro oblonga (larga), el barbero debe:", options: ["Add width at the sides and minimize height on top to create the illusion of a shorter, wider face", "Add maximum height on top to elongate the face further", "Keep hair extremely short all over", "Use a high fade to draw attention upward"], options_es: ["Añadir anchura en los lados y minimizar la altura en la parte superior para crear la ilusión de un rostro más corto y ancho", "Añadir máxima altura en la parte superior para alargar aún más el rostro", "Mantener el cabello extremadamente corto en todo el cabello", "Usar un degradé alto para llamar la atención hacia arriba"], correct: 0, explanation: "An oblong face is already long and narrow. Width at the sides and reduced height on top creates the illusion of a more balanced, oval face shape. Avoid styles that emphasize vertical length." },
  { id: 191, question: "For a client with a heart (inverted triangle) face shape, the recommended approach is:", question_es: "Para un cliente con forma de rostro de corazón (triángulo invertido), el enfoque recomendado es:", options: ["Add fullness at the jaw area and minimize width at the temples to balance the wider forehead", "Maximize volume at the temples and top", "Keep hair very short all over to reduce face width", "Add height at the crown to elongate the face"], options_es: ["Añadir volumen en el área de la mandíbula y minimizar la anchura en las sienes para equilibrar la frente más ancha", "Maximizar el volumen en las sienes y la parte superior", "Mantener el cabello muy corto en todo el cabello para reducir el ancho del rostro", "Añadir altura en la coronilla para alargar el rostro"], correct: 0, explanation: "A heart face has a wide forehead and narrow chin/jaw. Styles that add fullness at the jaw and chin while keeping the temples less wide help balance the face toward a more oval proportion." },
  { id: 192, question: "The term 'weight line' in haircutting refers to:", question_es: "El término 'línea de peso' en el corte de cabello se refiere a:", options: ["The area where hair appears heaviest or densest, created by the perimeter of a graduated or one-length cut", "The part of the head where hair is naturally thickest", "The elevation at which scissors are held during cutting", "The density assessment done before beginning a haircut"], options_es: ["El área donde el cabello parece más pesado o denso, creada por el perímetro de un corte graduado o de un solo largo", "La parte de la cabeza donde el cabello es naturalmente más grueso", "La elevación a la que se sostienen las tijeras durante el corte", "La evaluación de densidad realizada antes de comenzar un corte de cabello"], correct: 0, explanation: "The weight line is the visual line in a haircut where hair appears heaviest — typically the perimeter of a graduated (stacked) cut or the solid line of a blunt cut. Managing the weight line determines where bulk sits in the finished style." },
  { id: 193, question: "When cutting very curly (type 4) natural hair, a barber must account for:", question_es: "Al cortar cabello natural muy rizado (tipo 4), un barbero debe tener en cuenta:", options: ["Significant shrinkage — curly hair can appear 50–75% shorter than its actual stretched length", "The fact that curly hair requires higher elevation cuts only", "That razor cutting is preferred over scissor cutting for all curly types", "The need to wet the hair after cutting for an accurate length assessment"], options_es: ["Contracción significativa — el cabello rizado puede parecer 50–75% más corto que su longitud real estirada", "El hecho de que el cabello rizado requiere solo cortes de elevación más alta", "Que el corte con navaja se prefiere sobre el corte con tijeras para todos los tipos rizados", "La necesidad de mojar el cabello después de cortar para una evaluación precisa de la longitud"], correct: 0, explanation: "Tightly coiled (type 4) natural hair has significant shrinkage — sometimes 50-75% — meaning stretched-out hair is much longer than it appears in its natural state. Barbers must cut less than intended to account for this." },
  { id: 194, question: "A 'dry cut' (cutting hair dry before or without wetting) is preferable when:", question_es: "Un 'corte en seco' (cortar el cabello seco antes de o sin mojarlo) es preferible cuando:", options: ["Working with very curly or coily hair to see the natural curl pattern and true length in its natural state", "Performing a blunt one-length cut for precision", "Using a razor for texturizing", "Cutting fine, straight hair for a smooth finish"], options_es: ["Trabajando con cabello muy rizado o en espiral para ver el patrón de rizos natural y la longitud real en su estado natural", "Realizando un corte recto de un solo largo para mayor precisión", "Usando una navaja para texturizar", "Cortando cabello fino y liso para un acabado suave"], correct: 0, explanation: "Cutting natural coily/curly hair dry (or in its natural state) allows the barber to see exactly how the curl pattern falls and where length shrinks, enabling more accurate cutting without the distortion of wet hair." },
  { id: 195, question: "The 'afro' style is maintained by:", question_es: "El estilo 'afro' se mantiene mediante:", options: ["Picking out or combing natural coily hair away from the head to create a rounded, voluminous shape, with trimming to even the silhouette", "Relaxing the hair chemically before styling", "Wetting and blow-drying hair straight", "Braiding the hair tightly overnight to create volume"], options_es: ["Peinar o sacar el cabello natural en espiral lejos de la cabeza para crear una forma redondeada y voluminosa, con recorte para igualar la silueta", "Relajar el cabello químicamente antes de peinarlo", "Mojar y secar el cabello con secador para alisarlo", "Trenzar el cabello apretadamente durante la noche para crear volumen"], correct: 0, explanation: "An afro is created and maintained by gently picking out (using an afro pick) natural coily hair to maximum volume, then trimming the outer perimeter to create a symmetrical, rounded silhouette." },
  { id: 196, question: "When performing a clipper fade on a client with a dark complexion, the barber must be especially careful to:", question_es: "Al realizar un degradé con cortadora en un cliente con tez oscura, el barbero debe ser especialmente cuidadoso para:", options: ["Achieve a seamless blend because harsh lines and uneven blending are more visible against darker skin tones", "Use a higher guard number than usual", "Start the fade lower on the head", "Avoid using any guard attachment at the fade line"], options_es: ["Lograr una mezcla perfecta porque las líneas duras y la mezcla desigual son más visibles contra tonos de piel más oscuros", "Usar un número de guarda más alto de lo habitual", "Comenzar el degradé más abajo en la cabeza", "Evitar usar cualquier accesorio de guarda en la línea de degradé"], correct: 0, explanation: "On darker skin, unblended lines and imperfections in a fade are more visually apparent. Careful blending with overlapping passes, multiple guard sizes, and a sharp blade are essential for a seamless result." },
  { id: 197, question: "The 'temple fade' (temp fade) specifically fades the hair at:", question_es: "El 'temple fade' (degradé de sienes) específicamente desvanece el cabello en:", options: ["The temple area, blending hair from skin or very short at the temples into the longer hair above", "The nape only", "The crown and top of the head", "The entire side from ear to ear"], options_es: ["El área de las sienes, mezclando el cabello desde la piel o muy corto en las sienes hacia el cabello más largo de arriba", "Solo la nuca", "La coronilla y la parte superior de la cabeza", "Todo el lado de oreja a oreja"], correct: 0, explanation: "A temple fade (temp fade) focuses specifically on the temple area — fading the hair at the temples very short or to skin while keeping more length elsewhere. It creates a clean, sharp look around the temple recession area." },
  { id: 198, question: "Hair is generally cut in what state to achieve the most accurate length when performing a blunt or precision cut?", question_es: "El cabello generalmente se corta en qué estado para lograr la longitud más precisa al realizar un corte recto o de precisión?", options: ["Wet, because water relaxes the natural curl and wave, allowing hair to be combed to its true length", "Dry, because wet hair stretches and will appear shorter after drying", "Damp (towel dried) only for curly hair", "After blow-drying completely straight"], options_es: ["Húmedo, porque el agua relaja el rizo y la onda natural, permitiendo peinar el cabello a su longitud real", "Seco, porque el cabello mojado se estira y parecerá más corto después del secado", "Apenas húmedo (secado con toalla) solo para cabello rizado", "Después de secar completamente con secador"], correct: 0, explanation: "Wet cutting is preferred for blunt and precision cuts because water relaxes waves and curls, allowing hair to be combed to its true natural length. This helps achieve an accurate, even cut that hangs correctly when dry." },
  { id: 199, question: "Scissors used for haircutting should be:", question_es: "Las tijeras usadas para el corte de cabello deben:", options: ["Sharp, properly tensioned at the pivot screw, and sanitized between each client", "Replaced every six months regardless of condition", "Stored in a UV cabinet after each client", "Sharpened with a home whetstone weekly"], options_es: ["Afiladas, correctamente tensadas en el tornillo pivote y desinfectadas entre cada cliente", "Reemplazadas cada seis meses independientemente de la condición", "Almacenadas en un gabinete UV después de cada cliente", "Afiladas con una piedra de afilar doméstica semanalmente"], correct: 0, explanation: "Scissors must be kept sharp (dull blades push and fold hair rather than cutting cleanly), properly tensioned (not too loose — hair catches — not too tight — causes hand fatigue), and disinfected between each client." },
  { id: 200, question: "The pivot screw tension of haircutting scissors should be:", question_es: "La tensión del tornillo pivote de las tijeras para corte de cabello debe ser:", options: ["Set so the blades fall open to about 45 degrees when one handle is released — not too loose or too tight", "As tight as possible to prevent the blades from separating", "Completely loose so the blades can swing freely", "Adjusted to be completely locked after each use"], options_es: ["Ajustada para que las hojas se abran a aproximadamente 45 grados cuando se suelta un mango — ni demasiado suelta ni demasiado apretada", "Lo más apretada posible para evitar que las hojas se separen", "Completamente suelta para que las hojas puedan oscilar libremente", "Ajustada para quedar completamente bloqueada después de cada uso"], correct: 0, explanation: "The ideal pivot screw tension allows the blades to fall open to approximately 45 degrees when one handle is released. Too tight causes hand fatigue; too loose causes hair to fold into the blades rather than being cut cleanly." },
  { id: 201, question: "The 'French crop' (textured crop) hairstyle features:", question_es: "El estilo de cabello 'corte francés' (corte texturizado) presenta:", options: ["Short hair on top with a short fringe (bangs) that falls forward, often paired with a fade or taper on the sides", "Long hair swept to the side from a deep side part", "Maximum volume at the crown with close-cropped sides", "An undercut with the top left very long and slicked back"], options_es: ["Cabello corto en la parte superior con un flequillo corto que cae hacia adelante, a menudo combinado con un degradé o cónico en los lados", "Cabello largo barrido hacia un lado desde una separación lateral profunda", "Máximo volumen en la coronilla con lados muy cortos", "Un corte inferior con la parte superior muy larga y peinada hacia atrás"], correct: 0, explanation: "The French crop (textured crop or Ivy League crop) has short, textured hair on top with a short fringe falling forward on the forehead. The sides and back are tapered or faded. It is popular and low-maintenance." },
  { id: 202, question: "What is the primary purpose of using a diffuser attachment on a blow dryer?", question_es: "¿Cuál es el propósito principal de usar un accesorio difusor en un secador de cabello?", options: ["To disperse air flow broadly and gently, reducing frizz and enhancing the natural curl or wave pattern", "To concentrate air flow for directional straight styling", "To increase heat intensity at the roots", "To dry hair faster by maximizing airflow velocity"], options_es: ["Dispersar el flujo de aire de manera amplia y suave, reduciendo el frizz y realzando el patrón natural de rizos u ondas", "Concentrar el flujo de aire para el peinado direccional recto", "Aumentar la intensidad del calor en las raíces", "Secar el cabello más rápido maximizando la velocidad del flujo de aire"], correct: 0, explanation: "A diffuser spreads air over a wide area at reduced velocity, allowing curly and wavy hair to dry without disruption of the curl pattern. This minimizes frizz and enhances natural texture." },
  { id: 203, question: "A 'taper' neckline differs from a 'fade' in that a taper:", question_es: "Una nuca 'cónica' difiere de un 'degradé' en que una cónica:", options: ["Gradually shortens hair toward the hairline without taking it to skin level, maintaining some hair throughout", "Takes the hair completely to skin at the lowest point", "Is only applied to the sides of the head, not the nape", "Uses only one guard size for the entire blend"], options_es: ["Acorta gradualmente el cabello hacia la línea del cabello sin llevarlo al nivel de la piel, manteniendo algo de cabello en todo el recorrido", "Lleva el cabello completamente a nivel de piel en el punto más bajo", "Se aplica solo a los lados de la cabeza, no a la nuca", "Usa solo un tamaño de guarda para toda la mezcla"], correct: 0, explanation: "A taper shortens hair progressively toward the hairline but does not go to skin. A fade can go to skin (skin fade/bald fade). Tapers maintain some visible hair at the shortest point, while fades can eliminate it completely." },
  { id: 204, question: "The 'Mohawk' style is characterized by:", question_es: "El estilo 'Mohawk' se caracteriza por:", options: ["A strip of longer hair down the center of the head from front to back, with the sides shaved or cut very short", "Even length all over with a slight texture on top", "Long hair on one side and shaved on the other", "Closely cropped hair all over with a peak of longer hair only at the forehead"], options_es: ["Una franja de cabello más largo en el centro de la cabeza de frente a nuca, con los lados rapados o cortados muy cortos", "Longitud uniforme en todo el cabello con una ligera textura en la parte superior", "Cabello largo en un lado y rapado en el otro", "Cabello muy corto en todo el cabello con una cresta de cabello más largo solo en la frente"], correct: 0, explanation: "The Mohawk features a central strip of longer hair running from the forehead to the nape, with the sides shaved or cut very close. A 'faux hawk' keeps more length on the sides but creates a similar center-strip appearance when styled." },
  { id: 205, question: "When holding scissors properly, the ring finger and thumb are placed in the shear rings while the:", question_es: "Al sostener las tijeras correctamente, el dedo anular y el pulgar se colocan en los aros de las tijeras mientras que el:", options: ["Index and middle fingers rest on the outside of the blade for control; the pinky rests on the finger rest", "Middle finger operates the moving blade", "Pinky finger goes inside the ring for stability", "Index finger closes the blades during cutting"], options_es: ["El índice y el dedo medio descansan en el exterior de la hoja para mayor control; el meñique descansa en el apoyo para el dedo", "El dedo medio opera la hoja móvil", "El dedo meñique va dentro del aro para mayor estabilidad", "El dedo índice cierra las hojas durante el corte"], correct: 0, explanation: "Proper scissor grip: thumb in one ring, ring finger in the other ring (or just the ring finger depending on design), index and middle fingers along the blade for control, and little finger on the tang/finger rest for balance." },
  { id: 206, question: "The 'high and tight' military haircut is characterized by:", question_es: "El corte de cabello militar 'high and tight' se caracteriza por:", options: ["Closely shaved or very short sides starting high on the head (at the parietal ridge or above) with a small amount of short hair left on top", "Long top with medium-length sides blended together", "A low fade with long, flowing hair on top", "Even length all over using a #4 guard"], options_es: ["Lados muy rapados o muy cortos que comienzan alto en la cabeza (en la cresta parietal o más arriba) con una pequeña cantidad de cabello corto en la parte superior", "Parte superior larga con lados de longitud media mezclados juntos", "Degradé bajo con cabello largo y fluido en la parte superior", "Longitud uniforme en todo el cabello usando una guarda #4"], correct: 0, explanation: "The 'high and tight' is a military-regulation cut with the sides shaved starting very high on the head (near the parietal ridge or above), leaving only a small, short patch of hair on top. It is clean, disciplined, and low maintenance." },
  { id: 207, question: "Which factor most determines whether a barber should recommend a razor cut or scissors for a client's haircut?", question_es: "¿Qué factor determina principalmente si un barbero debe recomendar un corte con navaja o con tijeras para el corte de cabello de un cliente?", options: ["Hair texture — razor cutting works best on fine-to-medium hair; coarse or curly hair may frizz with razor cutting", "The length of the cut — razor is always used for short cuts", "The client's face shape and desired style", "Whether the client prefers wet or dry cutting"], options_es: ["Textura del cabello — el corte con navaja funciona mejor en cabello fino a medio; el cabello grueso o rizado puede encresparse con el corte con navaja", "La longitud del corte — la navaja siempre se usa para cortes cortos", "La forma del rostro del cliente y el estilo deseado", "Si el cliente prefiere el corte húmedo o en seco"], correct: 0, explanation: "Razor cutting thins and bevels hair ends, creating soft texture — ideal for fine-to-medium straight hair. On coarse or curly hair, razoring can cause frizz and roughen the cuticle, making scissors a better choice." },
  { id: 208, question: "The term 'graduation' in haircutting describes a cut where:", question_es: "El término 'graduación' en el corte de cabello describe un corte donde:", options: ["Hair lengths progressively increase from shorter layers underneath to longer lengths on the outside, creating a stacked or wedge effect", "All hair is cut to the same length at 90-degree elevation", "Hair is cut progressively shorter from the crown to the nape", "The perimeter is cut bluntly with no variation in length"], options_es: ["Las longitudes del cabello aumentan progresivamente desde capas más cortas debajo hasta longitudes más largas afuera, creando un efecto apilado o de cuña", "Todo el cabello se corta a la misma longitud a 90 grados de elevación", "El cabello se corta progresivamente más corto desde la coronilla hasta la nuca", "El perímetro se corta de forma recta sin variación de longitud"], correct: 0, explanation: "Graduation creates a build-up of weight through the stacking of layers — the shorter interior layers fall under the longer exterior, creating volume and a stacked or wedge shape. It is achieved at 45-degree elevation." },
  { id: 209, question: "A 'drop fade' is distinctive because:", question_es: "Un 'drop fade' (degradé caído) es distintivo porque:", options: ["The fade line drops lower behind the ear and at the nape, following the curve of the head, creating an arc shape", "The fade begins lower on the head than a standard low fade", "The fade drops from the temple all the way to the chin", "The top hair drops down over the fade line in a disconnected style"], options_es: ["La línea de degradé cae más baja detrás de la oreja y en la nuca, siguiendo la curva de la cabeza, creando una forma de arco", "El degradé comienza más abajo en la cabeza que un degradé bajo estándar", "El degradé cae desde la sien hasta la barbilla", "El cabello superior cae sobre la línea de degradé en un estilo desconectado"], correct: 0, explanation: "A drop fade curves downward behind the ear, following the natural shape of the head rather than maintaining a level horizontal line. The curve 'drops' lower at the back, creating a distinctive arc that frames the back of the head." },
  { id: 210, question: "When performing a scissor cut on a client, the non-cutting hand should:", question_es: "Al realizar un corte con tijeras en un cliente, la mano que no corta debe:", options: ["Comb and hold the hair section with consistent tension to guide the cut", "Hold the client's head steady throughout the cut", "Hold the spray bottle to keep hair wet", "Rest on the client's shoulder for support"], options_es: ["Peinar y sostener la sección de cabello con tensión constante para guiar el corte", "Mantener la cabeza del cliente estable durante todo el corte", "Sostener la botella de spray para mantener el cabello húmedo", "Descansar en el hombro del cliente para mayor apoyo"], correct: 0, explanation: "The non-dominant (non-cutting) hand combs and holds each section with consistent, even tension. This hand acts as a guide — the scissors follow the fingers to cut the hair at the desired length and angle." },
  { id: 211, question: "A 'texturized' or 'tapered' fade finish at the top of the fade line is created using:", question_es: "Un acabado 'texturizado' o 'cónico' en la parte superior de la línea de degradé se crea usando:", options: ["Open clipper (taper lever up) or a guard-less clipper flicked outward with a scooping motion to soften the line", "A sharp trimmer outlining the exact top of the fade", "Scissors to cut along the top of the fade line", "A razor to blend the line with the hair above"], options_es: ["Cortadora abierta (palanca de cono arriba) o cortadora sin guarda con un movimiento hacia afuera y curvado para suavizar la línea", "Una recortadora afilada delineando exactamente la parte superior del degradé", "Tijeras para cortar a lo largo de la parte superior de la línea de degradé", "Una navaja para mezclar la línea con el cabello de arriba"], correct: 0, explanation: "Softening the top of the fade line uses the clipper with the taper lever open (or no guard) with an outward scooping or flicking wrist motion. This technique 'feathers' the line rather than creating a harsh edge." },
  { id: 212, question: "Which face shape benefits most from a haircut with fuller sides and reduced height on top?", question_es: "¿Qué forma de rostro se beneficia más de un corte de cabello con lados más llenos y altura reducida en la parte superior?", options: ["Oblong (long) face shape", "Round face shape", "Square face shape", "Diamond face shape"], options_es: ["Forma de rostro oblonga (larga)", "Forma de rostro redonda", "Forma de rostro cuadrada", "Forma de rostro de diamante"], correct: 0, explanation: "An oblong face is long and narrow. Adding width at the sides and keeping height on top low creates the illusion of a shorter, wider (more oval) face. Height would only further elongate an already long face." },
  { id: 213, question: "The 'wave' hairstyle (360 waves) is achieved on coily/curly hair by:", question_es: "El estilo de cabello 'waves' (360 waves) se logra en cabello en espiral/rizado mediante:", options: ["Brushing hair in a consistent circular pattern, applying wave pomade, and using a durag or wave cap to train the hair flat while it sets", "Applying a relaxer to soften the curl pattern", "Using a curling iron on short natural hair", "Wet-setting with flexi rods overnight"], options_es: ["Cepillar el cabello en un patrón circular consistente, aplicar pomada para waves y usar un durag o gorra de waves para entrenar el cabello plano mientras se fija", "Aplicar un relajador para suavizar el patrón de rizos", "Usar una rizadora en cabello natural corto", "Ondular en húmedo con flexi rods durante la noche"], correct: 0, explanation: "360 waves require consistent brushing in a circular wave pattern, pomade or wave grease to lay the hair, and compression with a durag or wave cap. The hair is gradually trained to form a 360-degree wave pattern around the head." },
  { id: 214, question: "When trimming a mustache, the barber should:", question_es: "Al recortar un bigote, el barbero debe:", options: ["Comb the mustache hair downward, then trim along the natural lip line for a clean edge, removing any stray hairs", "Apply hot towel first to soften the mustache hair before trimming", "Always shave the entire mustache area and start fresh", "Use only straight scissors without any comb"], options_es: ["Peinar el cabello del bigote hacia abajo, luego recortar a lo largo de la línea natural de los labios para un borde limpio, eliminando los cabellos sueltos", "Aplicar toalla caliente primero para suavizar el cabello del bigote antes de recortar", "Siempre afeitar toda el área del bigote y comenzar de nuevo", "Usar solo tijeras rectas sin ningún peine"], correct: 0, explanation: "Mustache trimming involves combing hair downward to its natural fall, trimming along the lip line with scissors or trimmer, and using the trimmer to define the philtrum line (under the nose) and outer corners." },
  { id: 215, question: "Sideburns should be checked for symmetry by:", question_es: "Las patillas deben verificarse para simetría mediante:", options: ["Standing in front of the client and visually comparing both sides, adjusting by using the barber chair or hand position as a reference", "Using a ruler to measure from the ear to the bottom of each sideburn", "Asking the client to tell you when they look even", "Checking only one side and mirroring it without visual comparison"], options_es: ["Pararse frente al cliente y comparar visualmente ambos lados, ajustando usando la silla de barbería o la posición de la mano como referencia", "Usar una regla para medir desde la oreja hasta la parte inferior de cada patilla", "Pedir al cliente que le diga cuando se vean parejas", "Revisar solo un lado y reflejarlo sin comparación visual"], correct: 0, explanation: "Symmetry is checked by standing in front of the client and using visual reference points (ear level, cheekbone, corner of eye). A barber should step back frequently to compare both sides during the service." },
  { id: 216, question: "The 'skin taper' differs from a full 'skin fade' in that a skin taper:", question_es: "El 'taper skin' difiere de un 'skin fade' completo en que un skin taper:", options: ["Takes the hair to skin only at the very edge of the hairline, with a blend above", "Takes the hair to skin at all points along the sides and back", "Uses only a guard #0 without going to bare skin", "Blends the sides but leaves the nape untouched"], options_es: ["Lleva el cabello a la piel solo en el borde de la línea del cabello, con una mezcla por encima", "Lleva el cabello a la piel en todos los puntos a lo largo de los lados y la nuca", "Usa solo una guarda #0 sin llegar a la piel desnuda", "Mezcla los lados pero deja la nuca sin tocar"], correct: 0, explanation: "A skin taper touches the hair down to skin only at the very edge of the hairline, blending upward from there. A full skin fade goes to skin at a higher starting point and blends up over a broader area." },
  { id: 217, question: "What type of comb is best for detangling wet curly or coily hair before cutting?", question_es: "¿Qué tipo de peine es mejor para desenredar el cabello rizado o en espiral húmedo antes de cortar?", options: ["Wide-tooth comb, which glides through curls without breaking them", "Fine-tooth rattail comb for precision", "Teasing comb for volume", "Rubber-based clipper comb for thick hair"], options_es: ["Peine de dientes anchos, que se desliza por los rizos sin romperlos", "Peine de cola de dientes finos para precisión", "Peine de cardado para volumen", "Peine de clipper de base de goma para cabello grueso"], correct: 0, explanation: "A wide-tooth comb is gentle on wet curly/coily hair — wide teeth glide through the curl pattern without snagging, catching, or breaking fragile wet strands. Fine-tooth combs can break and damage wet curly hair." },
  { id: 218, question: "When creating a 'box fade,' what defines the top portion of the style?", question_es: "Al crear un 'box fade', ¿qué define la parte superior del estilo?", options: ["The top hair is left full and natural (unpicked to volume), creating a box or rectangular silhouette above the faded sides", "The top is cut short in a box-like square shape", "A geometric pattern is cut into the top of the head", "The sides are tapered into a box shape at the base"], options_es: ["El cabello superior se deja lleno y natural (sin peinar hacia volumen), creando una silueta de caja o rectangular sobre los lados desvanecidos", "La parte superior se corta corta en forma cuadrada", "Se corta un patrón geométrico en la parte superior de la cabeza", "Los lados se afilan en forma de caja en la base"], correct: 0, explanation: "A box fade combines a high fade on the sides with natural, picked-out coily/curly hair left at full volume on top. The natural hair forms a box or rectangular silhouette above the clean fade — merging the afro shape with fade technique." },
  { id: 219, question: "Hair art (design cuts) involves creating patterns, lines, or designs in the hair using:", question_es: "El arte en cabello (cortes de diseño) implica crear patrones, líneas o diseños en el cabello usando:", options: ["A trimmer or razor to shave specific areas down to skin, creating contrast with the surrounding hair", "Scissors to cut intricate patterns in long hair", "Chemical lighteners to bleach specific sections", "Braiding techniques to create raised patterns"], options_es: ["Una recortadora o navaja para rapar áreas específicas hasta la piel, creando contraste con el cabello circundante", "Tijeras para cortar patrones intrincados en cabello largo", "Aclaradores químicos para blanquear secciones específicas", "Técnicas de trenzado para crear patrones elevados"], correct: 0, explanation: "Hair art and design cuts use a trimmer (and sometimes a razor) to shave patterns, words, or geometric designs into the hair. The shaved (skin-level) areas create contrast against the surrounding hair, forming the visible design." },
  { id: 220, question: "The length of hair left on top by clipper guard sizes, from shortest to longest, follows which pattern?", question_es: "La longitud del cabello dejado en la parte superior por los tamaños de guarda de la cortadora, de más corta a más larga, sigue qué patrón?", options: ["Each higher guard number leaves approximately 1/8 inch more length (e.g., #1 = 1/8\", #2 = 1/4\", #3 = 3/8\")", "Each higher guard number cuts half the previous length", "Guards are measured in millimeters with #1 = 1mm", "Guard numbers indicate the blade angle, not the length"], options_es: ["Cada número de guarda más alto deja aproximadamente 1/8 de pulgada más de longitud (p. ej., #1 = 1/8\", #2 = 1/4\", #3 = 3/8\")", "Cada número de guarda más alto corta la mitad de la longitud anterior", "Las guardas se miden en milímetros con #1 = 1mm", "Los números de guarda indican el ángulo de la cuchilla, no la longitud"], correct: 0, explanation: "Standard Oster/Wahl clipper guards increase in 1/8-inch increments: Guard #1 = 1/8 in, #2 = 1/4 in, #3 = 3/8 in, #4 = 1/2 in, #5 = 5/8 in, #6 = 3/4 in, #7 = 7/8 in, #8 = 1 in." },
  { id: 221, question: "The 'rattail comb' is primarily used for:", question_es: "El 'peine de cola de rata' se usa principalmente para:", options: ["Sectioning hair with precision using the pointed tail end, and for detailed styling", "Detangling wet curly hair", "Combing large sections for uniform layers", "Teasing hair at the roots for volume"], options_es: ["Seccionar el cabello con precisión usando el extremo puntiagudo de la cola, y para el peinado detallado", "Desenredar el cabello rizado húmedo", "Peinar secciones grandes para capas uniformes", "Cardar el cabello en las raíces para volumen"], correct: 0, explanation: "The rattail (pintail) comb has a pointed metal or plastic tail used for precise sectioning, creating parts, and detailed styling work. The comb portion is used for smoothing and combing small sections." },
  { id: 222, question: "A barber performing a service notices that the client's scalp has a large open wound or abrasion. The barber should:", question_es: "Un barbero que realiza un servicio nota que el cuero cabelludo del cliente tiene una herida abierta grande o abrasión. El barbero debe:", options: ["Stop the service, clean the area gently, and advise the client to seek medical attention if needed; do not perform scalp services over open wounds", "Continue the service while avoiding the wound area", "Apply antiseptic directly to the wound and proceed", "Cover the wound with a band-aid and continue the haircut"], options_es: ["Detener el servicio, limpiar el área suavemente y aconsejar al cliente que busque atención médica si es necesario; no realizar servicios del cuero cabelludo sobre heridas abiertas", "Continuar el servicio evitando el área de la herida", "Aplicar antiséptico directamente a la herida y continuar", "Cubrir la herida con una curita y continuar el corte de cabello"], correct: 0, explanation: "Services should not be performed over open wounds or abrasions on the scalp. These represent breaks in the skin integrity that increase both the barber's and client's risk of infection. The client should be referred to a physician." },
  { id: 223, question: "Which haircutting elevation creates the most weight at the perimeter of a haircut?", question_es: "¿Qué elevación de corte de cabello crea más peso en el perímetro de un corte de cabello?", options: ["0 degrees (no elevation — hair held flat against the head)", "45 degrees (graduation elevation)", "90 degrees (uniform layer elevation)", "180 degrees (hair held above the head)"], options_es: ["0 grados (sin elevación — cabello sostenido plano contra la cabeza)", "45 grados (elevación de graduación)", "90 grados (elevación de capas uniformes)", "180 grados (cabello sostenido por encima de la cabeza)"], correct: 0, explanation: "At 0 degrees, hair is held flat against the head with no lifting. All hair falls to the perimeter after cutting, creating maximum weight at the line. This is the foundation of the one-length (blunt) cut." },
  { id: 224, question: "The 'Ivy League' cut (Harvard clip or Princeton clip) differs from a crew cut in that it:", question_es: "El corte 'Ivy League' (Harvard clip o Princeton clip) difiere de un crew cut en que:", options: ["Has enough length on top to be parted and combed to the side, while the crew cut is typically combed forward", "Is a longer version with hair reaching the collar", "Has shaved sides while the crew cut does not", "Uses only scissors while the crew cut uses only clippers"], options_es: ["Tiene suficiente longitud en la parte superior para ser separado y peinado hacia un lado, mientras que el crew cut generalmente se peina hacia adelante", "Es una versión más larga con cabello que llega al cuello", "Tiene lados rapados mientras que el crew cut no", "Usa solo tijeras mientras que el crew cut usa solo cortadoras"], correct: 0, explanation: "The Ivy League (Harvard/Princeton clip) is slightly longer on top than a crew cut, allowing the hair to be parted and combed to the side. It is a classic, conservative style often associated with academic institutions." },
  { id: 225, question: "Proper cleaning and care of a straight razor includes:", question_es: "La limpieza y el cuidado adecuados de una navaja recta incluyen:", options: ["Wiping clean after use, disinfecting with an EPA-registered disinfectant or 70% alcohol, and storing in a dry, clean container", "Soaking in water between clients to keep the blade from drying out", "Sharpening before every client on a leather strop only", "Storing the blade open to allow air circulation"], options_es: ["Limpiar después del uso, desinfectar con un desinfectante registrado por la EPA o alcohol al 70% y almacenar en un recipiente seco y limpio", "Remojar en agua entre clientes para evitar que la hoja se seque", "Afilar antes de cada cliente solo en una correa de cuero", "Almacenar la hoja abierta para permitir la circulación del aire"], correct: 0, explanation: "Straight razors (multi-use/replaceable-blade type) must be cleaned, disinfected with EPA-registered disinfectant between clients, and stored properly. The blade strop is for honing the edge, not cleaning or disinfecting." },
  { id: 226, question: "Hair grows from the scalp at an average rate of approximately:", question_es: "El cabello crece desde el cuero cabelludo a una tasa promedio de aproximadamente:", options: ["1/2 inch (1.25 cm) per month", "1 inch per week", "1/4 inch per month", "2 inches per month"], options_es: ["1/2 pulgada (1.25 cm) por mes", "1 pulgada por semana", "1/4 de pulgada por mes", "2 pulgadas por mes"], correct: 0, explanation: "On average, human scalp hair grows approximately 1/2 inch (about 1.25 cm) per month, or roughly 6 inches (15 cm) per year. Growth rate can vary with age, health, season, and individual genetics." },
  { id: 227, question: "Which layer of the hair strand contains the pigment (melanin) that determines hair color?", question_es: "¿Qué capa del cabello contiene el pigmento (melanina) que determina el color del cabello?", options: ["The cortex", "The cuticle", "The medulla", "The hair root"], options_es: ["El córtex", "La cutícula", "La médula", "La raíz del cabello"], correct: 0, explanation: "Melanin (hair color pigment) is produced by melanocytes and is found within the cortex — the middle layer of the hair strand. The cuticle is the outer protective layer; the medulla is the innermost layer (not present in all hair)." },
  { id: 228, question: "The cuticle of the hair strand serves to:", question_es: "La cutícula del cabello sirve para:", options: ["Protect the inner cortex, reflect light (giving hair shine), and control moisture exchange with the environment", "Provide the hair's natural color and pigment", "Determine the curl pattern of the hair", "Anchor the hair into the follicle"], options_es: ["Proteger el córtex interno, reflejar la luz (dando brillo al cabello) y controlar el intercambio de humedad con el ambiente", "Proporcionar el color natural y el pigmento del cabello", "Determinar el patrón de rizos del cabello", "Anclar el cabello en el folículo"], correct: 0, explanation: "The cuticle is the outermost layer of overlapping scales. It protects the cortex, reflects light (healthy cuticle = shiny hair), and regulates moisture absorption. Damaged cuticle = dull, porous, and brittle hair." },
  { id: 229, question: "The three phases of the hair growth cycle are:", question_es: "Las tres fases del ciclo de crecimiento del cabello son:", options: ["Anagen (growth), catagen (transition), and telogen (resting/shedding)", "Active, dormant, and regenerative", "Growth, rest, and death", "Follicular, shaft, and terminal phases"], options_es: ["Anágeno (crecimiento), catágeno (transición) y telógeno (descanso/caída)", "Activo, dormante y regenerativo", "Crecimiento, descanso y muerte", "Fases folicular, eje y terminal"], correct: 0, explanation: "Hair grows in three cycles: Anagen (active growth — 2–7 years), Catagen (transitional phase — 2–3 weeks), and Telogen (resting/shedding phase — 2–4 months). Most scalp hair is in the anagen phase at any given time." },
  { id: 230, question: "What does a barber check when assessing a client's hair before a chemical or cutting service?", question_es: "¿Qué verifica un barbero al evaluar el cabello de un cliente antes de un servicio químico o de corte?", options: ["Texture, density, porosity, elasticity, and growth patterns", "Only the hair color and length", "The style the client shows in a photo", "The type of products currently in the hair"], options_es: ["Textura, densidad, porosidad, elasticidad y patrones de crecimiento", "Solo el color y la longitud del cabello", "El estilo que el cliente muestra en una foto", "El tipo de productos actualmente en el cabello"], correct: 0, explanation: "A thorough hair analysis before any service includes assessing: texture (diameter), density (hairs per sq inch), porosity (cuticle condition), elasticity (cortex health), and growth patterns (cowlicks, whorls) — all of which affect the outcome." },
  { id: 231, question: "A barber should stand or sit in a position during cutting that:", question_es: "Un barbero debe pararse o sentarse en una posición durante el corte que:", options: ["Maintains proper posture (straight back, relaxed shoulders) and positions the work at a comfortable height to prevent ergonomic injury", "Leans over the client to see the cut up close at all times", "Requires bending at the waist for better access to the nape", "Keeps one hand in the client's chair for stability at all times"], options_es: ["Mantiene una postura adecuada (espalda recta, hombros relajados) y posiciona el trabajo a una altura cómoda para prevenir lesiones ergonómicas", "Se inclina sobre el cliente para ver el corte de cerca en todo momento", "Requiere doblarse desde la cintura para mejor acceso a la nuca", "Mantiene una mano en la silla del cliente para mayor estabilidad en todo momento"], correct: 0, explanation: "Barbers are at risk for repetitive stress injuries (back, neck, wrist, shoulder). Proper posture — straight back, relaxed shoulders, adjusting the chair height so work is at elbow level — prevents long-term musculoskeletal injuries." },
]

function fmt(q) {
  return `  { id: ${q.id}, topic: ${topic}, topic_es: ${topic_es}, psi_topic: ${psi_topic}, psi_topic_es: ${psi_topic_es}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

const lines = q.map(fmt).join('\n')
const existing = readFileSync(FILE, 'utf8')
writeFileSync(FILE, existing + lines + '\n', 'utf8')
console.log(`Appended ${q.length} Haircutting questions (ids ${q[0].id}–${q[q.length-1].id})`)
